-- Mod-authored victory and defeat screen descriptions, ru_RU overlay.
-- Baseline in CivVAccess_VictoryDescStrings_en_US.lua.
CivVAccess_Strings = CivVAccess_Strings or {}

CivVAccess_Strings["TXT_KEY_CIVVACCESS_VICTORYDESC_MISSING"] = "Для этого экрана нет описания."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_VICTORYDESC_VICTORY_CULTURAL"] =
    "С травянистой вершины холма, затенённой тёмным деревом, две фигуры сидят силуэтами и смотрят вдаль на золотой город. Под ними толпа переходит через арочный каменный мост, по сторонам которого на постаментах стоят классические статуи, а за ним поднимается купольный зал. За полосой парковой зелени линия горизонта вздымается стройными футуристическими башнями, растворяющимися в янтарной дымке. Люди рассыпаны по лужайкам: дети бегут под воздушным змеем, высоко взмывшим на своей нити, фигура прогуливается под жёлтым зонтом от солнца, а вдали сквозь туман на воде белеют паруса. Вся сцена пропитана тёплым золотым светом, наполовину поздним днём и наполовину сном, и птицы разбросаны по небу."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_VICTORYDESC_VICTORY_DIPLOMATIC"] =
    "Церемония на зелёной лужайке перед высокой белой плитой штаб-квартиры Организации Объединённых Наций. На переднем плане толпа стоит к вам спиной, одетая в костюмы, мантии и головные платки многих народов, а справа со штатива снимает телеоператор. Лужайку кольцом окружают флагштоки с десятками национальных флагов, среди которых узнаются Соединённые Штаты и Мексика. В центре под раскидистыми деревьями на квадратном постаменте покоится большой каменный глобус, его материки подняты рельефом. Перед ним ждёт вереница детей в народных костюмах разных стран; женщина в синем наклоняется, чтобы что-то передать маленькой девочке в жёлтом платье, которая тянется за этим вверх. Клумбы красных и белых цветов окаймляют тихий пруд внизу кадра, и мягкий серый дневной свет всё уравнивает."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_VICTORYDESC_VICTORY_DOMINATION"] =
    "Парад победы, написанный плакатными красками, сплошь золотыми, оливковыми и красными. Справа на переднем плане молодой офицер в белом парадном мундире с золотым шитьём на плече сжимает древко огромного красного знамени, что развевается через всё небо; его фуражка с красным околышем несёт золотую кокарду. Позади него ряды солдат в таких же белых мундирах стоят с примкнутыми штыками, вскинутыми вертикально у плеча, и из колонны поднимаются новые красные знамёна. Над парадом на высоком постаменте возвышается бронзовая статуя полководца на шагающем коне, а за ней - большое купольное здание капитолия. Тонкие красные стяги вьются лентами через сияющее жёлто-зелёное небо, а тёмные кипарисы и подёрнутые дымкой горы замыкают даль."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_VICTORYDESC_VICTORY_SPACE_RACE"] =
    "Глубокий космос, взгляд снизу вверх на огромную орбитальную станцию. Её тёмный корпус тянется вдоль верха кадра, по нижней стороне идут ряды высоких тепло освещённых окон и зеленовато светящихся отсеков. Клочья пара проплывают по металлу. Плоские решётчатые солнечные панели расходятся от корпуса на фермовых штангах, а с дальнего конца вниз по правой стороне кадра спускается длинная обшитая панелями ферменная башня. Внизу ночная сторона планеты простирается вдаль в густом фиолетовом и винном цвете, её горизонт выгибается вдоль нижней части сцены. Солнце как раз поднимается над этим горизонтом бело-золотой вспышкой, что освещает полосы розовых и кремовых облаков вдоль изгиба. На переднем плане одинокий крылатый корабль пересекает тьму, оставляя длинный светящийся бирюзовый след, а вдали меньшие суда поблёскивают зелёным и оранжевым на фоне звёзд."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_VICTORYDESC_VICTORY_TIME"] =
    "Иллюстрация с обложки игры, увеличенная во весь экран. Глобус, собранный из старинных карт в тонах сепии, господствует в кадре, а название Sid Meier's Civilization протянуто поперёк него рельефными буквами из полированного металла, продетыми сквозь гигантскую латунную римскую цифру пять. В верхнем левом углу наклеена потёртая финская почтовая марка с всадником на украшенном коне в честь эпоса Калевала. Вокруг неё впечатаны блёклые почтовые штемпели. За глобусом лежит коллаж из бумаги, окрашенной в бирюзовый цвет, латунное кольцо меридиана выгибается вокруг нижнего края глобуса, и свет падает слева сверху, словно на диковинку под лампой."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_VICTORYDESC_DEFEAT"] =
    "Мёртвая империя под пустынным небом. Колоссальная каменная голова статуи лежит щекой на песке, с закрытыми глазами и безмятежным лицом, а рядом из земли тянется обломанная каменная рука с пальцами, скрюченными к небу. Вокруг идёт раскоп: в землю переднего плана врезаны траншеи, линия столбов с проволокой образует ограду, а одинокая фигура в бледной одежде стоит на деревянном помосте лестницы, совсем крошечная рядом с изучаемым ею ликом. Слева в стороне ждёт вьючное животное. Пустая долина уходит назад мимо разбросанных стоящих обломков к плосковершинным столовым горам на горизонте. Всё песочного и ржавого цвета под тонким синим небом, одинокие ровные пески Озимандии Шелли простираются вдаль."
